Unfortunately due to how reflection works we will need to expand this function a bit more to properly handle text matches. Right now the code works completely fine, except that the `objectURL` and `objectType` properties get output as `object_url` and `object_type` in json which does not match the casing we use for the rest of the JSON output. I think the code below should work for what we want. 

```go
var TextMatchFields = []string{
	"fragment",
	"matches",
	"url",
	"type",
	"property",
}

func (code Code) ExportData(fields []string) map[string]interface{} {
	v := reflect.ValueOf(code)
	data := map[string]interface{}{}
	for _, f := range fields {
		switch f {
		case "repository":
			data[f] = code.Repo.ExportData(RepositoryFields)
		case "textMatches":
			matches := make([]interface{}, 0, len(code.TextMatches))
			for _, match := range code.TextMatches {
				matches = append(matches, match.ExportData(TextMatchFields))
			}
			data[f] = matches
		default:
			sf := fieldByName(v, f)
			data[f] = sf.Interface()
		}
	}
	return data
}

func (textMatch TextMatch) ExportData(fields []string) map[string]interface{} {
	v := reflect.ValueOf(textMatch)
	data := map[string]interface{}{}
	for _, f := range fields {
		switch f {
		default:
			sf := fieldByName(v, f)
			data[f] = sf.Interface()
		}
	}
	return data
}
```
